//! The files whose leading comment says that a tool wrote them: `<!-- Generated by render-guides.mjs; edit … -->`,
//! `# Generated from tool-permissions.json …`, `// Code generated by protoc-gen-go. DO NOT EDIT.`, `@generated`.
//!
//! The rule reads only the leading block of comments, in the comment syntax of the file, and only a comment that starts
//! with the words of a generator (or holds `@generated`): `generated` in the middle of a sentence of a hand-written
//! comment is no marker, and a Markdown heading is no comment.

/// The comment lines of the leading block that the rule reads
const MAX_HEADER_LINES: usize = 5;

/// The bytes of the start of a text that the rule needs: the leading block after a front matter of a few lines
pub const HEADER_BYTES: usize = 4096;

/// The front matter of a Markdown file the rule skips, in lines
const MAX_FRONT_MATTER_LINES: usize = 40;

/// The starts of a comment that a generator writes, in lowercase
const MARKER_STARTS: [&str; 19] = [
  "generated by",
  "generated from",
  "generated with",
  "generated automatically",
  "this file is generated",
  "this file was generated",
  "this file is auto-generated",
  "this file was auto-generated",
  "this file is autogenerated",
  "this file is automatically generated",
  "this file was automatically generated",
  "this is a generated file",
  "this is an auto-generated file",
  "this is an autogenerated file",
  "auto-generated",
  "autogenerated",
  "automatically generated",
  "code generated by",
  "do not edit: generated",
];

/// The comment syntax of a file
struct Syntax {
  line: &'static [&'static str],
  block: &'static [(&'static str, &'static str)],
}

const XML: Syntax = Syntax {
  line: &[],
  block: &[("<!--", "-->")],
};
const C: Syntax = Syntax {
  line: &["//"],
  block: &[("/*", "*/")],
};
const HASH: Syntax = Syntax { line: &["#"], block: &[] };
const INI: Syntax = Syntax { line: &[";", "#"], block: &[] };
const DASHES: Syntax = Syntax { line: &["--"], block: &[] };
const LISP: Syntax = Syntax { line: &[";"], block: &[] };
const UNKNOWN: Syntax = Syntax {
  line: &["#", "//"],
  block: &[("/*", "*/"), ("<!--", "-->")],
};

/// The comment syntax of `path` by its name; `None` for a format without comments (JSON) and for the ignore files,
/// whose `# Generated by Cargo` names the tool that started a file people keep
fn syntax_of(path: &str) -> Option<&'static Syntax> {
  let name = crate::names::file_name(path);
  if name.starts_with('.') && name.ends_with("ignore") {
    return None;
  }
  match name {
    "BUILD" | "WORKSPACE" | "Dockerfile" | "Makefile" | "GNUmakefile" | "CMakeLists.txt" | ".gitattributes" | ".editorconfig" => return Some(&HASH),
    _ => {}
  }
  let extension = name.rsplit_once('.').map_or("", |(_, extension)| extension);
  Some(match extension.to_ascii_lowercase().as_str() {
    "json" => return None,
    "md" | "markdown" | "mdx" | "html" | "htm" | "xhtml" | "xml" | "svg" | "vue" | "iml" | "plist" | "xsd" | "xsl" => &XML,
    "rs" | "ts" | "tsx" | "mts" | "cts" | "js" | "jsx" | "mjs" | "cjs" | "kt" | "kts" | "java" | "go" | "c" | "h" | "cc" | "cpp" | "cxx" | "hpp" | "m" | "mm" | "cs" | "swift"
    | "scala" | "dart" | "groovy" | "gradle" | "proto" | "css" | "scss" | "less" | "php" | "jsonc" | "json5" | "zig" | "sol" | "thrift" | "fbs" => &C,
    "py" | "pyi" | "rb" | "sh" | "bash" | "zsh" | "fish" | "toml" | "yaml" | "yml" | "rules" | "bzl" | "bazel" | "star" | "cmake" | "r" | "pl" | "pm" | "conf" | "properties"
    | "ps1" | "nix" | "tf" | "hcl" | "graphql" | "gql" | "mk" | "cfg" | "env" | "dockerfile" => &HASH,
    "ini" => &INI,
    "sql" | "lua" | "hs" | "elm" => &DASHES,
    "el" | "clj" | "cljs" | "lisp" | "scm" => &LISP,
    _ => &UNKNOWN,
  })
}

/// The comment of the leading block of `text` that says a tool wrote the file at `path`, without its comment
/// markers: `Generated by community/.ai/render-guides.mjs; edit community/.ai/*`. `text` is the start of the file,
/// `HEADER_BYTES` are enough
pub fn generated_header(path: &str, text: &str) -> Option<String> {
  let syntax = syntax_of(path)?;
  let mut lines = text.lines().peekable();
  // a front matter of Markdown, a shebang, an XML declaration and blank lines come before the header
  if std::ptr::eq(syntax, &XML) && lines.peek().is_some_and(|line| line.trim_end() == "---") {
    lines.next();
    let mut closed = false;
    for line in lines.by_ref().take(MAX_FRONT_MATTER_LINES) {
      if line.trim_end() == "---" {
        closed = true;
        break;
      }
    }
    if !closed {
      return None;
    }
  }
  let mut first = true;
  while let Some(line) = lines.peek() {
    let line = line.trim();
    if line.is_empty() || (first && line.starts_with("#!")) || line.starts_with("<?xml") {
      lines.next();
      first = false;
    } else {
      break;
    }
  }
  let mut comments = Vec::new();
  let mut closer: Option<&str> = None;
  for line in lines {
    if comments.len() == MAX_HEADER_LINES {
      break;
    }
    let line = line.trim();
    let text = if let Some(end) = closer {
      match line.split_once(end) {
        Some((inside, _)) => {
          closer = None;
          inside
        }
        None => line,
      }
    } else if let Some((open, close)) = syntax.block.iter().find(|(open, _)| line.starts_with(open)) {
      let rest = &line[open.len()..];
      if let Some((inside, _)) = rest.split_once(close) {
        inside
      } else {
        closer = Some(close);
        rest
      }
    } else if let Some(open) = syntax.line.iter().find(|open| line.starts_with(*open)) {
      // `///`, `//!`, `##`: the doc and the heading forms of a line comment
      line[open.len()..].trim_start_matches(['/', '!', '#', ';', '-'])
    } else {
      break;
    };
    // the `*` of the lines inside a block comment
    comments.push(text.trim().trim_start_matches('*').trim());
  }
  comments.iter().find(|comment| is_marker(comment)).map(|comment| (*comment).to_string())
}

fn is_marker(comment: &str) -> bool {
  let lower = comment.to_lowercase();
  lower.contains("@generated") || MARKER_STARTS.iter().any(|start| lower.starts_with(start))
}
